function M.Build(parent, origin)
	parent = parent or workspace:FindFirstChild("ShadowRealm") or workspace
	local folder = parent:FindFirstChild("ShadowRealm_Collision")
	if not folder then
		folder = Instance.new("Folder")
		folder.Name = "ShadowRealm_Collision"
		folder.Parent = parent
	else
		folder:ClearAllChildren()
	end

	local hasOrigin = (typeof(origin) == "Vector3")
	local baseCF = hasOrigin and CFrame.new(origin) or nil
	local idx = 0

	for _, c in ipairs(CYL) do
		idx += 1
		local p = Instance.new("Part")
		p.Name = "ShadowRealm_Floor_" .. idx
		p.Shape = Enum.PartType.Cylinder
		p.Anchored = true
		p.CanCollide = true
		p.CanQuery = true
		p.CanTouch = true
		p.CastShadow = false
		p.Transparency = 1
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Size = Vector3.new(c[4], c[5], c[5])
		local lcf = CFrame.new(c[1], c[2], c[3]) * CYL_ROT
		p.CFrame = hasOrigin and (baseCF * lcf) or lcf
		p.Parent = folder
	end

	for _, b in ipairs(BLK) do
		idx += 1
		local p = Instance.new("Part")
		p.Name = "ShadowRealm_Floor_" .. idx
		p.Shape = Enum.PartType.Block
		p.Anchored = true
		p.CanCollide = true
		p.CanQuery = true
		p.CanTouch = true
		p.CastShadow = false
		p.Transparency = 1
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Size = Vector3.new(b[4], b[5], b[6])
		local lcf = CFrame.new(b[1], b[2], b[3])
		local yaw = b[7]
		local slp = b[8]
		if yaw and yaw ~= 0 then
			lcf = lcf * CFrame.Angles(0, yaw, 0)
		end
		if slp and slp ~= 0 then
			lcf = lcf * CFrame.Angles(0, 0, slp)
		end
		p.CFrame = hasOrigin and (baseCF * lcf) or lcf
		p.Parent = folder
	end

	folder:SetAttribute("ColliderCount", idx)
	return folder
end

